def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    my = [h[0] for h in history]

    last_op = op[-1]
    last_me = my[-1]

    op_def = 0
    for a in op:
        if a == 'D':
            op_def += 1
    my_def = 0
    for a in my:
        if a == 'D':
            my_def += 1

    # opponent defection streak at the end
    op_def_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            op_def_streak += 1
        else:
            break

    # opponent cooperation streak at the end
    op_c_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            op_c_streak += 1
        else:
            break

    recent_len = 10
    if n < 10:
        recent_len = n
    recent_op_def = 0
    for i in range(n - recent_len, n):
        if op[i] == 'D':
            recent_op_def += 1
    recent_op_c = recent_len - recent_op_def

    # All-out opponent: never cooperate against a sustained defector late.
    if op_def == n:
        return 'D'

    # Mutual defection spiral: try to escape, but only sometimes.
    if last_op == 'D' and last_me == 'D' and op_def_streak >= 2:
        if n < 90:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # If opponent just defected after a long CC run, retaliate once.
    if last_op == 'D':
        # Very cooperative overall opponent: single punishment then forgive.
        if op_def <= 2 and n >= 3:
            if op_def_streak == 1 and last_me == 'C':
                return 'D'
            if op_def_streak == 2:
                return 'D'
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        # Opponent mostly cooperative: punish then return to cooperation.
        if op_def > 0 and op_def * 3 <= n:
            if op_def_streak >= 3:
                return 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        # Opponent is frequently defecting: defect back.
        return 'D'

    # Opponent cooperated last round.
    # If opponent has been very cooperative, mostly cooperate with rare probes.
    if op_def <= 1:
        # Endgame exploitation of an all-cooperator.
        if n >= 97:
            return 'D'
        # Rare, deterministic probe to avoid being purely exploitable.
        if n > 20 and recent_op_def == 0 and n % 37 == 0:
            return 'D'
        return 'C'

    # Opponent has defected before but cooperated last round.
    if op_def * 2 <= n:
        # Mostly cooperative opponent: occasional probing late.
        if n >= 80 and recent_op_def <= 1:
            if n % 11 == 0 and rng.random() < 0.5:
                return 'D'
        return 'C'

    # Opponent is mixed or predominantly defecting.
    # If they are currently cooperating, cooperate but stay cautious.
    if op_c_streak >= 3:
        # Reward a fresh cooperation streak, but defect occasionally.
        if op_def > n * 3 // 5:
            if rng.random() < 0.3:
                return 'D'
            return 'C'
        return 'C'

    # Long-term defector with only brief cooperation: defect.
    if op_def > op_c_streak and op_def * 2 > n:
        return 'D'

    # Endgame: if opponent has been exploitable, defect in final rounds.
    if n >= 95:
        if op_def < n // 3 and last_op == 'C':
            return 'D'

    # Default cautious cooperation.
    return 'C'
